#pragma once#include "BaseReader.h"class KOR : public KBaseReader{public:  KOR();  virtual std::string GetType() const  {    return "OR";  }  virtual void GetSettings( tVectoredString_ &set, tParamsCont_ &params )  {    __super::GetSettings( set, params );    set = m_InversedPins;  }protected:  virtual BOOL OnParsingSingleText( std::string &szText, RECTL *rc );private:  int m_CurParameterID;  int m_ReadParams;  tVectoredString_ m_InversedPins;  std::string szLast;};//////////////////////////////////////////////////////////////////////////class KORFactory : public TIntrusivePtrImpl<IParamReaderFactory>{public:  virtual IParameterReadPtr CreateReader()  {    IParameterReadPtr ptr;    ptr = new KOR();    return ptr;  }};